# =====================================================================
# Twelve C - account deletion fix + futuristic UI patch
# Auto-detects each target file under $repoRoot by its distinctive path
# suffix, writes new content (base64-decoded to avoid ANY quoting issues),
# then stages/commits/pushes once at the end.
# =====================================================================

$repoRoot = "C:\Users\24kcee\Downloads\twelve-c-all-phases-FIXED\twelve-c"

function Write-PatchedFile {
    param(
        [string]$SuffixPath,   # e.g. 'phase2-backend\app\api\routes\auth.py'
        [string]$Base64Content
    )
    $leaf = Split-Path $SuffixPath -Leaf
    $matches = Get-ChildItem -Path $repoRoot -Recurse -Filter $leaf -File -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName.Replace('/', '\') -like ('*' + $SuffixPath.Replace('/', '\')) }

    if ($matches.Count -eq 0) {
        # Not found (likely a brand-new file) - create it at repoRoot\<suffix>.
        $fullPath = Join-Path $repoRoot $SuffixPath
        $dir = Split-Path $fullPath -Parent
        if (-not (Test-Path -LiteralPath $dir)) {
            New-Item -ItemType Directory -Path $dir -Force | Out-Null
        }
        Write-Host "  NEW   $SuffixPath"
    } else {
        $fullPath = $matches[0].FullName
        Write-Host "  PATCH $fullPath"
    }

    $bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
}

Write-Host "=== Twelve C patch: account deletion fix + futuristic UI ===" -ForegroundColor Cyan

Write-PatchedFile -SuffixPath 'phase2-backend\scripts\__init__.py' -Base64Content @'

